linguísticos do texto 12A1AAA.

Item: No trecho “ao procurar alguma coisa que se ache escondida” (R. 30 e 31), o pronome “que” exerce a função de complemento da forma verbal “ache”.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Língua Portuguesa$q$ and t.topic_order=2 and t.block_name not ilike '%Hist%' limit 1) where exam_year=2018 and career_name=$q$Agente de Polícia Federal$q$ and item_number=21 and content_status='under_review';
-- @@
