update public.official_exam_questions set review_note=$q$Conferido no texto compilado do Decreto-Lei 200/1967 (Planalto, 27/09/2026): art. 4º — a Administração Federal compreende a direta (Presidência e Ministérios) e a indireta (autarquias, empresas públicas, sociedades de economia mista e fundações públicas). Gabarito C confere.$q$, question_text=$q$Comando:
Acerca da organização da administração pública brasileira, julgue
os itens subsequentes.

Item: Sob a perspectiva do critério formal adotado pelo Brasil, somente é administração pública aquilo determinado como tal pelo ordenamento jurídico brasileiro, independentemente da atividade exercida. Assim, a administração pública é composta exclusivamente pelos órgãos integrantes da administração direta e pelas entidades da administração indireta.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Noções de Direito Administrativo$q$ and t.topic_order=1 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Decreto-Lei nº 200/1967$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm$q$)), law_version_checked_at=now() where exam_year=2018 and career_name=$q$Agente de Polícia Federal$q$ and item_number=25 and content_status='under_review';
